INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (1, 1, 'Long-Bodied Grey Dog', '3', 'Creature - Dog', 1, 1, 1, 'FlashReachWhen this creature enters, create a tapped Treasure token. (It''s an artifact with "Tap, Sacrifice this token: Add one mana of any color.")', 'Beorn''s dogs took bowls and platters and knives and wooden spoons and quickly laid them on the trestle tables.', '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/04D7595BFD498E91D2E2AC23CD655462BBD838F08523D1D125B5FBA62F3ADFF3.webp', NULL);
