INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (4, 4, 'Belladonna Took', '1One white mana', 'Legendary Creature - Halfling Citizen', 3, 1, 4, 'Whenever a token you control enters, you gain 1 life if this is the first time this ability has resolved this turn. If it''s the second time, draw a card. If it''s the third time, put a +1/+1 counter on each creature you control.', 'Once in a while, members of the Took clan would go and have adventures.', '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/007AF89E844906124959A40939DD57E667B03E6E197B5FF1CCD38D97BD068EE4.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (5, 5, 'Bilbo''s Gambit', '1One white mana', 'Instant', 3, 1, 5, 'Gift a Treasure (You may promise an opponent a gift as you cast this spell. If you do, they create a Treasure token before its other effects. It''s an artifact with "Tap, Sacrifice this token: Add one mana of any color.")Return target spell to its owner''s hand. If the gift was promised, players can''t cast spells this turn.', NULL, NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/1C6F8971A16DD4F73F13FE01288FE07FF0D62B85D35FC01CD297035B89BF7E94.webp', NULL);
