INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (11, 11, 'Eagle of the Great Shelf', '4One white mana', 'Creature - Bird Soldier', 2, 1, 9, 'FlyingWhenever this creature attacks, it gets +1/+1 until end of turn for each other creature you control.', 'The Goblins hated the Eagles and feared them, but could not reach their lofty seats or drive them from the mountains.', '2', '5', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/7780282EBD179E0FAF15583C232DFE4F78596B0BA11028F16EEEDD5486E9B044.webp', NULL);
