INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (13, 13, 'Esgaroth Garrison', '4One white mana', 'Creature - Human Soldier', 1, 1, 11, 'Esgaroth Garrison''s power is equal to the number of creatures you control.When this creature enters, recruit. (Draw a card, then discard a card. If you discarded a nonland card, create a 1/1 white Human Soldier creature token.)', '"I suggest we go to Lake-town," said Bilbo. "What else is there?"', '*', '5', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/01BFE43AA1D5A87145B0C47610DB9FE02707293244363E8C506DB9350B7D56B7.webp', NULL);
