INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (18, 18, 'Lake-town Lookout', 'One white mana', 'Creature - Human Scout', 1, 1, 15, 'When this creature dies, recruit. (Draw a card, then discard a card. If you discarded a nonland card, create a 1/1 white Human Soldier creature token.)', '"Look! The lights again! Last night the watchmen saw them start and fade from midnight until dawn. Something is happening up there."', '1', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/483F7D3DBED9667074FB28B883691E9BAE496D334DBB7BFF6A69C14433BF2C6A.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (19, 19, 'Lake-town Toymaker', '3One white mana', 'Creature - Human Artificer', 2, 1, 16, 'At the beginning of combat on your turn, if you''ve drawn two or more cards this turn, another target creature you control gets +3/+0 and gains first strike until end of turn.', 'In the great days of old, when Dale in the North was rich and prosperous, Lake-town flourished.', '3', '4', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/4686EF4BCF0106B51568FDC275BB195E639D3149F7F01AF10B7EE20B4A3E1B35.webp', NULL);
