INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (22, 22, 'The Mountain-king''s Return', '2One white mana', 'Enchantment - Saga', 2, 1, 17, '(As this Saga enters and after your draw step, add a lore counter. Sacrifice after III.)I - Recruit. (Draw a card, then discard a card. If you discarded a nonland card, create a 1/1 white Human Soldier creature token.)II - Return target creature card with mana value 3 or less from your graveyard to the battlefield.III - Put a +1/+1 counter on up to one target creature.', NULL, NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/EBB35B90CE16FCE0A6519D9A0DE75E99DF5F25BF95A0738879B87A57CE849703.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (23, 23, 'Ori, Keeper of Songs', '2One white mana', 'Legendary Creature - Dwarf Bard', 1, 1, 18, 'Storied (If you control three or more artifacts, legendaries, and/or Sagas, you have an enduring story for the rest of the game.)As long as you have an enduring story, Ori gets +1/+0 and has vigilance.', 'The music began all at once, so sudden and sweet that Bilbo forgot everything else.', '3', '3', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/4C39BD29F13DC14BEDF5DD27A27E2BF364E7BBAC07333A6F9F2A7A78FF4A806F.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (24, 24, 'The Queen of Dale', '1One white mana', 'Legendary Creature - Human Noble', 4, 1, 19, 'Whenever an opponent casts their first noncreature spell each turn, you recruit. (Draw a card, then discard a card. If you discarded a nonland card, create a 1/1 white Human Soldier creature token.)', 'Dale may grow to reclaim its former glory and splendor, as in the days before the Dragon came.', '2', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/8847AFC406F4B2F94E30FD29E0C85F1B5FEBDCE94F23D64A327DFA2E17AF2B95.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (25, 25, 'Roads Go Ever, Ever On', '1One white mana', 'Enchantment - Saga', 3, 1, 17, '(As this Saga enters and after your draw step, add a lore counter. Sacrifice after IV.)I - Search your library for up to two basic Plains cards, exile them, then shuffle. You gain 2 life.II, III - Put a card exiled with this Saga into its owner''s hand.IV - Whenever you attack this turn, target creature you control gets +1/+1 until end of turn for each Plains you control.', NULL, NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/93672EE45E3AB5B548F345C604D31029E1B8439700F546CF6A926C3B4446E1E7.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (26, 26, 'Settle the Wreckage', '2One white manaOne white mana', 'Instant', 3, 1, 20, 'Exile all attacking creatures target player controls. That player may search their library for that many basic land cards, put those cards onto the battlefield tapped, then shuffle.', 'There was a hiss, a gushing whirl, and then silence. And that was the end of Smaug and Esgaroth.', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/F86DCFB5118D2A1328050E310E384B03DB7B2443490603FE15FDEFD5F92DE0E9.webp', NULL);
