INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (67, 67, 'Front Porch Sentries', '1One black mana', 'Creature - Goblin Soldier', 1, 1, 44, 'When this creature dies, target creature an opponent controls gets -1/-1 until end of turn.', 'It was deep, deep dark, such as only Goblins that have taken to living in the heart of the mountain can see through.', '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/D5EAF5A17401E42D1B3FCE65BFB307F30333F7C72B2E3422E87B2C8599AC5B66.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (68, 68, 'Gathering of Darkness', '3One black mana', 'Sorcery', 2, 1, 45, 'Return up to one target creature card from your graveyard to your hand.Amass Goblins 3. (Put three +1/+1 counters on an Army you control. It''s also a Goblin. If you don''t control an Army, create a 0/0 black Goblin Army creature token first.)', '"Alas! Bolg of the North is coming!"
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (69, 69, 'Gnashing of Teeth', '1One black manaOne black mana', 'Sorcery', 2, 1, 36, 'Choose one -* Target creature gets -5/-5 until end of turn. If that creature would die this turn, exile it instead.* Creatures target player controls get -1/-1 until end of turn.', 'The rage of the wolves was terrible to see, and the commotion they made filled all the forest.', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/DD2C47AB8428111E2036692114957E1A9039C2BC37543BB3B7FC955775B52E04.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (70, 70, 'Gollum, Riddle Master', '1One black mana', 'Legendary Creature - Halfling Horror', 4, 1, 29, 'As Gollum enters, choose odd or even. (Zero is even.)Whenever an opponent casts a spell with mana value of the chosen quality, choose one that hasn''t been chosen -* Put a +1/+1 counter on Gollum.* Each opponent loses 2 life and you gain 2 life.* Draw a card.', NULL, '3', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/CF12C2479F8945CE9D86BF730959BE206BADE149FEBB2C3BB1537852A95B99D9.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (71, 71, 'Gollum, Silent Slinker', '3One black mana', 'Legendary Creature - Halfling Horror', 1, 1, 40, 'Menace (This creature can''t be blocked except by two or more creatures.)//ADV//Meager MealOne black manaSorcery - AdventurePut a +1/+1 counter on up to one target creature. Target player gains 2 life. (Then exile this card. You may cast the creature later from exile.)', 'He rowed about quietly on the lake. Never a ripple did he make, not he.', '4', '3', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/63F82B2771ADCBB2C707F55B76C4948015097AED92012F8AC55C68C9A2D2DED3.webp', NULL);
