INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (75, 75, 'Head of the Hunt', '2One black manaOne black mana', 'Creature - Wolf', 3, 1, 46, 'FlashIf a creature an opponent controls would die, exile it instead. When you do, create a 2/2 green Wolf creature token.', 'The Wargs planned to come by night upon the villages nearest the mountains. If their plan had been carried out, there would have been none left there next day.', '4', '3', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/F386005BFC22DA2530414427B7E1023E73B4F428E3918581466433BC9819AAA8.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (76, 76, 'Inside Information', 'XOne black manaOne black mana', 'Sorcery', 4, 1, 49, 'Exile the top X cards of target opponent''s library. You may play those cards this turn. If you cast a spell this way, pay life equal to its mana value rather than pay its mana cost.', '"Old fool!" Bilbo thought. "Why, there is a large patch in the hollow of his left breast as bare as a snail out of its shell!"', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/4A0C77042FEDA6F378C7C5720D85052304B1706214D943DB0FAA2BB9534DDAA7.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (77, 77, 'The Master of Lake-town', '1One black manaOne black mana', 'Legendary Creature - Human Advisor', 3, 1, 50, 'DeathtouchWhenever a player loses life, that player mills that many cards. (Damage causes loss of life.)When The Master of Lake-town dies, draw a card for each graveyard with seven or more cards in it.', NULL, '3', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/8DD1F2D7E2FEF1FEA4F5EAAE785A5B932F1938864741A360FE328D75B7EFF149.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (78, 78, 'Nighthowl Pursuer', 'One black mana', 'Creature - Wolf', 2, 1, 7, 'Menace (This creature can''t be blocked except by two or more creatures.)Ferocious - Whenever this creature attacks while you control a creature with power 4 or greater, this creature gets +2/+2 until end of turn.', '"What shall we do?" cried Bilbo. "Escaping Goblins to be caught by wolves!"', '1', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/8FE11DCEE05F459DBF04E2E0BB0C4EB390E722A5022C0FED33B8FDCD8DB02D25.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (79, 79, 'Rage into the Valley', '2One black mana', 'Sorcery', 1, 1, 51, 'You draw a card and lose 1 life.Amass Goblins 2. (Put two +1/+1 counters on an Army you control. It''s also a Goblin. If you don''t control an Army, create a 0/0 black Goblin Army creature token first.)', 'The Goblin army poured in, driving wildly between the arms of the Mountain, seeking for the foe.', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/C93883C09E3AE67B8DD01E46F3224FAD967FF20F4AC687C85D32804646BF2F2F.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (80, 80, 'Ravening Warg', '1One black mana', 'Creature - Wolf', 1, 1, 52, 'DeathtouchFerocious - Whenever this creature attacks while you control a creature with power 4 or greater, you gain 2 life.', 'Goblins and wolves returned to the assault and soon forced their foes into a great ring, hemmed on all sides.', '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/AEE8F57210A97154E10C24D91DDCD99D3D074D78D73CB2F5FEC435EED010475C.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (81, 81, 'Reverent Howl', '2One black mana', 'Instant', 1, 1, 51, 'Choose one -* Target player draws two cards and loses 2 life.* Target creature gets +2/+2 and gains lifelink until end of turn.', 'The grey chief spoke in their dreadful language, and every now and then all the Wargs in the circle would answer together.', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/4521C88F9111E0F69168B098976E7D34B27820C0A1EF8F200849E93BDD841075.webp', NULL);
