INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (83, 83, 'The Sackville-Bagginses', '1One black mana', 'Legendary Creature - Halfling Citizen', 3, 1, 53, 'When The Sackville-Bagginses enter, you may sacrifice another creature or artifact. If you do, draw a card and create a Treasure token.Whenever you sacrifice a token, target opponent loses 1 life.', 'It took more than Bilbo showing up alive to convince some that he was not, in fact, "presumed dead."', '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/99B5A777C2B01A3BB8C885DB26AD61191BF05BDDEF6816A0B62A9C654A7A1410.webp', NULL);
