INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (104, 104, 'The Misty Mountains Cold', '2One red mana', 'Enchantment - Saga', 3, 1, 17, '(As this Saga enters and after your draw step, add a lore counter. Sacrifice after IV.)I, II, III, IV - Create a Treasure token. Then if you control four or more Treasures, sacrifice this Saga. If you do, create a 6/6 red Dragon creature token with flying. (A Treasure token is an artifact with "Tap, Sacrifice this token: Add one mana of any color.")', NULL, NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/F2C45F9F875C520D23998CC162A0D4CF87F0330EE1EA60409295EFE92180DC7E.webp', NULL);
