INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (111, 111, 'Smaug''s Fury', '1One red mana', 'Instant', 1, 1, 46, 'Target creature gets +3/+0 and gains reach and first strike until end of turn.', 'The Dwarves had barely time to fly back to the tunnel when Smaug came hurtling from the north, licking the mountainsides with flame, beating his great wings with a noise like a roaring wind.', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/5A9DF3CF493ABA4C9FA96DBA6B9A3EA5C5E6C38A68F10F24156F706C037E20CF.webp', NULL);
