INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (124, 124, 'Down in the Valley', '2One green mana', 'Enchantment - Saga', 3, 1, 17, '(As this Saga enters and after your draw step, add a lore counter. Sacrifice after IV.)I - Search your library for a basic land card, reveal it, put it into your hand, then shuffle.II - This Saga gains "Landfall - Whenever a land you control enters, create a 1/1 green Elf creature token."III, IV - Elves you control get +1/+0 and gain vigilance until end of turn.', NULL, NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/0612B7D3358E04C2F1BC4271AA79046EF3F6B15252375BFCA4B18E8EEC8FF4B3.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (125, 125, 'Galion, Elvenking''s Butler', '2One green manaOne green mana', 'Legendary Creature - Elf Advisor', 2, 1, 14, 'Whenever Galion attacks, choose up to one other target creature you control. Its base power and toughness become equal to Galion''s power and toughness until end of turn.', '"Here''s the old villain with his head on a jug! He''s been having a little feast all to himself!"
