INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (128, 128, 'Little Bear', '2One green mana', 'Creature - Bear', 1, 1, 7, 'FlashWhen this creature enters, untap another target creature you control. If that creature is a Bear, put a +1/+1 counter on it.', 'Even the littlest bears joined in important bear meetings and moonlit dances.', '3', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/72DF1D12A6CE43C0FFF01B12B919D7600A3F5E52BCB6F101BDEAAA8C23FE5610.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (129, 129, 'Mirkwood Pathmaker', '2One green mana', 'Creature - Elf Ranger', 2, 1, 49, 'Mirkwood Pathmaker''s power and toughness are each equal to the number of lands you control.', 'In the wide world, the Wood-Elves lingered in the twilight of the sun and moon but loved best the stars. They wandered in the great forests that grew tall in lands that were now lost.', '*', '*', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/6DDC50E1C2D1616BC97F18F6A28EB61E752EB6FC6746F70D14668ADA7F54AD09.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (130, 130, 'Nasty Little Rabbit', 'One green mana', 'Creature - Rabbit', 2, 1, 43, 'Ferocious - At the beginning of combat on your turn, if you control a creature with power 4 or greater, put a +1/+1 counter on this creature.', 'Beorn''s fences kept out Goblins and unwanted intruders, not hungry rabbits.', '1', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/BD03CD8C55061A96E4CFD1A4A75624E071FF02583A259D1EB0B2F63C12FF68E7.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (131, 131, 'The Notary Hobbits', '3One green manaOne green mana', 'Legendary Creature - Halfling Advisor', 3, 1, 14, 'When The Notary Hobbits enter, if they''re not a token, create two tokens that are copies of them, except the tokens aren''t legendary.Tap: Add One colorless mana for each Halfling you control.', 'Since Bilbo was presumed dead, his belongings were auctioned by three of the town''s best lawyers: Messrs. Grubb, Grubb, and Burrowes.', '1', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/4FF3CD1F15F992B46EA658C4AA57D28E25B873608CA50FE8FC3DDDC1D84EA9B1.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (132, 132, 'Old Fat Spider', '4One green manaOne green mana', 'Creature - Spider', 2, 1, 35, 'ReachThis creature can''t be blocked by creatures with power 2 or less.Whenever this creature becomes the target of a spell or ability an opponent controls, draw a card.', '"Old Tomnoddy can''t spy me!"
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (133, 133, 'Ordinary Bear', '3One green mana', 'Creature - Bear', 1, 1, 46, NULL, '"I should say there were little bears, large bears, ordinary bears, and gigantic big bears, all dancing outside from dark to nearly dawn."
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (134, 134, 'Part in Friendship', '4One green mana', 'Enchantment', 3, 1, 14, 'Whenever a nontoken creature you control dies, reveal cards from the top of your library until you reveal a creature card. If its mana value is less than or equal to the number of lands you control, put it onto the battlefield. Otherwise, put it into your hand. Put the rest on the bottom of your library in a random order. This ability triggers only once each turn.', NULL, NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/F26ACBE1E9CC03B3F6263E4BC832189E5296378528E63F1E97E393FCCE79C407.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (135, 135, 'Quarrel', '1One green mana', 'Instant', 1, 1, 53, 'Target creature you control deals damage equal to its power to target creature an opponent controls.', 'The shoving and name-calling was all in good fun, and Bilbo began to finally view the Dwarves as companions instead of strangers.', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/86783BD4B739EF4B2C31354704BE31ABDF49D6738CB6C323454028197253B166.webp', NULL);
