INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (137, 137, 'Through the Forest Gate', '6One green manaOne green mana', 'Sorcery', 3, 1, 37, 'Look at the top twenty cards of your library, put any number of land cards from among them onto the battlefield tapped, then shuffle. You gain 8 life.', '"Well, here is Mirkwood-the greatest of the forests of the northern world. I hope you like the look of it."
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (138, 138, 'Troll Negotiations', '2One green manaOne green mana', 'Sorcery', 2, 1, 60, 'Put two +1/+1 counters on target creature you control. Then it fights target creature an opponent controls. (Each deals damage equal to its power to the other.)', 'Suddenly they were fighting like dogs, and calling one another all sorts of perfectly true and applicable names in very loud voices.', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/AD689CD24C48588890371B4B56B1D9BE95B254488F2D6E68A880D1EBCEEA2551.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (139, 139, 'Warg Tactics', '1One green mana', 'Instant', 1, 1, 52, 'Choose one -* Destroy target creature with flying.* Put a +1/+1 counter on target creature you control. It gains trample and hexproof until end of turn. (It can''t be the target of spells or abilities your opponents control.)', NULL, NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/068811A1730F0D914A0A90EA2C0B4D19E74F2D2F69327895BA5559D402AEE84E.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (140, 140, 'Wargling', '1One green mana', 'Creature - Wolf', 1, 1, 52, 'Ferocious - Whenever this creature attacks while you control a creature with power 4 or greater, until end of turn, this creature gets +1/+0 and creatures you control gain trample.', 'From infancy, Warg pups were taught to hunt and harry and to fear and hate the presence of Humans.', '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/4366753CAA7E2F35A26CC6C6996D96A20BCE3029BA854906ECD4CFD19F2225D8.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (141, 141, 'Wilderland Scrounger', '4One green mana', 'Creature - Wolf', 2, 1, 7, 'Ferocious - Whenever this creature attacks while you control a creature with power 4 or greater, put a +1/+1 counter on each creature you control.', 'Wargs had little trouble devouring and digesting the most putrid of carcasses.', '3', '6', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/2DB836FA2BC76FE9F643BDD0163FD5973D1BCF03AA9285F2B526B54F5AF5A1AC.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (142, 142, 'Wood Elves', '2One green mana', 'Creature - Elf Scout', 1, 1, 24, 'When this creature enters, search your library for a Forest card, put that card onto the battlefield, then shuffle.', 'After the coming of Humans, the Wood-Elves took ever more and more to the gloaming and the dusk. Still Elves they were and remained-that is, Good People.', '1', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/0DA8CEDE57550B34E525D99CE0475947B49A016362466BD2BB2A46FE6DF9986F.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (143, 143, 'Woodland Weavemaster', '1One green mana', 'Creature - Elf Druid', 2, 1, 26, 'VigilanceWhenever another Elf you control enters, this creature gets +1/+1 until end of turn.Tap: Add X mana of any one color, where X is this creature''s power. Spend this mana only to cast Elf spells and activate abilities of Elf sources.', NULL, '1', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/20C7341D8244501AFAD73427B08AB308415BA126428BFFE581BF7D2F4F53AE55.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (144, 144, 'Bard, King of Dale', '4One white manaOne blue mana', 'Legendary Creature - Human Noble Archer', 4, 1, 4, 'Reach, vigilanceIf you would draw a card except the first one you draw in each of your draw steps, draw two cards instead.If one or more tokens would be created under your control, twice that many of those tokens are created instead.', NULL, '3', '5', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/6C804347002279CC03B855EB4A03D9311B06D8C23CD62CDC49774938C719FEF3.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (145, 145, 'Bard the Bowman', '1One white manaOne blue mana', 'Legendary Creature - Human Archer', 2, 1, 40, 'ReachWhenever you draw your second card each turn, put a +1/+1 counter on target creature. It gains lifelink until end of turn.', 'No one had dared to face the Dragon for many an age; nor would they have dared now, if it hadn''t been for the grim-voiced Bard urging them on.', '1', '3', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/7D71CFEBED018F88166E1AF22B99D1573851731FC2CCB325049359D25661B461.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (146, 146, 'Bard''s Company', '2One white manaOne blue mana', 'Creature - Human Citizen', 3, 1, 14, 'You may cast this spell as though it had flash if you control a Human.Other creatures you control get +1/+1.Whenever this creature enters or attacks, recruit. (Draw a card, then discard a card. If you discarded a nonland card, create a 1/1 white Human Soldier creature token.)', NULL, '2', '3', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/7D8FAB74CED193CC949F4BC400638E79159E1067936DEBF20FD39CCE1CA05147.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (147, 147, 'Bifur, Melodic Rider', '4One red or white hybrid manaOne red or white hybrid mana', 'Legendary Creature - Dwarf Bard', 2, 1, 6, 'Storied (If you control three or more artifacts, legendaries, and/or Sagas, you have an enduring story for the rest of the game.)Whenever Bifur enters or attacks, put a +1/+1 counter on target creature.As long as you have an enduring story, if a triggered ability of a Dwarf you control triggers, that ability triggers an additional time.', NULL, '4', '5', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/1C82385090DC000E39949129A4E7A3ED646E79A46C05A84B442B053E7B93A23D.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (148, 148, 'Bolg of the North', '3One black manaOne red mana', 'Legendary Creature - Goblin Soldier', 2, 1, 40, 'When Bolg enters, you may sacrifice another creature. When you do, Bolg deals damage equal to that creature''s power to another target creature. If excess damage was dealt this way, amass Goblins X, where X is that excess damage. (Put X +1/+1 counters on an Army you control. It''s also a Goblin. If you don''t control an Army, create a 0/0 black Goblin Army creature token first.)', NULL, '5', '5', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/79D476747CF81802C20436869A488CEEC38C5391CAC47065E9BE27378D762F66.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (149, 149, 'Bolg''s Company', 'One black manaOne red mana', 'Creature - Goblin Soldier', 3, 1, 54, 'This creature has haste as long as you control another Goblin.Tap, Sacrifice another Goblin: Add One black manaOne red mana.', 'Tidings they had gathered in secret ways; and in all the mountains there was a forging and an arming.', '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/9A89AF1A98E9B67E041A5DF64250EB425D307A4C7CF9A3C54D4E136595B8952D.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (150, 150, 'The Chief Warg', '2One black manaOne green mana', 'Legendary Creature - Wolf', 2, 1, 7, 'Menace (This creature can''t be blocked except by two or more creatures.)Ferocious - Whenever you attack while you control a creature with power 4 or greater, you draw a card and lose 1 life.', 'Even magic rings were not much use against wolves-especially against the evil packs that lived near Goblin-infested mountains.', '3', '3', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/9E69B33BB9715108364FF7D6E67041FAA04C4EFA499CA38C355C7A7F79C0F82D.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (151, 151, 'Chief Warg''s Company', '1One black manaOne green mana', 'Creature - Wolf', 3, 1, 48, 'TrampleThis creature can''t attack unless you control two or more other Wolves.At the beginning of your upkeep, create a 2/2 green Wolf creature token.', 'Seldom did Wargs venture near the dwellings of Humans, preferring instead to hunt and den over the Edge of the Wild.', '5', '3', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/28FADB50A31536DB66C276FC46E598F93377F240CB1FA5F8C3B32FA0C4090E44.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (152, 152, 'DГЎin''s Company', 'One red manaOne white mana', 'Creature - Dwarf Warrior', 3, 1, 61, 'This creature has lifelink as long as you control another Dwarf.When this creature enters, look at the top four cards of your library. You may reveal a Dwarf or Equipment card from among them and put it into your hand. Put the rest on the bottom of your library in a random order.', NULL, '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/617A1A8DFD4BD8C5DAD8EF398369924466B91CBF34044250F042A09BD5A8DA25.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (153, 153, 'Duskwatch Hunter', '2One black or green hybrid mana', 'Creature - Wolf', 1, 1, 62, 'This creature can''t be blocked by tokens.When this creature enters, put a +1/+1 counter on target creature.', 'Packs of evil wolves lived under the shadow of the Goblin-infested mountains, over the Edge of the Wild on the borders of the unknown.', '3', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pauper, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/4330BA5BB90D051DC23EB529580AEF7732114BFA93C4EA846EE9FF81DDB2E395.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (154, 154, 'Dwalin, Weaponmaster', '1One red or white hybrid mana', 'Legendary Creature - Dwarf Warrior', 3, 1, 63, 'First strikeWhenever Dwalin enters or attacks, put a hone counter on each Equipment you control. (Each hone counter on an Equipment grants +1/+0 to equipped creature.)', 'The Company had lost a great deal, but they had killed the Great Goblin and many others besides. All in all, they had the best of it.', '2', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/75E34A278EA7CFD97C7433000162B892DC79A0CE98F7BAEB0E48C8B42FC8FD34.webp', NULL);
