INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (156, 156, 'Fearsome Goblin Pair', '2One black or red hybrid mana', 'Creature - Goblin Soldier', 2, 1, 54, 'When this creature dies, amass Goblins 4. (Put four +1/+1 counters on an Army you control. It''s also a Goblin. If you don''t control an Army, create a 0/0 black Goblin Army creature token first.)', 'Out jumped the Goblins: big Goblins, small Goblins, great ugly-looking Goblins, lots of Goblins!', '1', '1', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/D2A34438F3D905361F89DAAAC8E5607AC1CFA4CA5F6FAEF05D8074170E1E1F01.webp', NULL);
