INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (159, 159, 'Large Bear', '3One black or green hybrid manaOne black or green hybrid mana', 'Creature - Bear', 2, 1, 52, 'Reach, trample, haste', '"I followed these bear tracks as far as the Carrock. There they disappeared into the river, but the water was too deep and strong beyond the rock for me to cross."
