INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (261, 296, 'Inside Information', 'XOne black manaOne black mana', 'Sorcery', 4, 1, 49, 'Exile the top X cards of target opponent''s library. You may play those cards this turn. If you cast a spell this way, pay life equal to its mana value rather than pay its mana cost.', '"Old fool!" Bilbo thought. "Why, there is a large patch in the hollow of his left breast as bare as a snail out of its shell!"', NULL, NULL, 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/B64FBEB644EB2EA025026414DBD7CBAE9ACECCA89F0BF4D85A891B567B120FEC.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (262, 297, 'The Master of Lake-town', '1One black manaOne black mana', 'Legendary Creature - Human Advisor', 3, 1, 50, 'DeathtouchWhenever a player loses life, that player mills that many cards. (Damage causes loss of life.)When The Master of Lake-town dies, draw a card for each graveyard with seven or more cards in it.', NULL, '3', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/0FCA6538E6A1B987909837376181D256A4B59FBB5A1E2E3734F9AB0589C72498.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (263, 298, 'Rhovanion Rampager', '2One black mana', 'Creature - Wolf', 3, 1, 32, 'Whenever this creature attacks, you may sacrifice another creature. If you do, put a number of +1/+1 counters on this creature equal to the sacrificed creature''s power.When this creature dies, amass Goblins X, where X is this creature''s power. (Put X +1/+1 counters on an Army you control. It''s also a Goblin. If you don''t control an Army, create a 0/0 black Goblin Army creature token first.)', NULL, '3', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/B0E0844476B0F4576DAEFC0EB16877AD98B8C42F530DC5BA32394672B0D63131.webp', NULL);
INSERT INTO public.cards (id, number, name, manacost, typeline, rarityid, setid, artistid, rulestext, flavortext, power, toughness, language, legalformats, imageurl, legal_formats) VALUES (264, 299, 'The Sackville-Bagginses', '1One black mana', 'Legendary Creature - Halfling Citizen', 3, 1, 53, 'When The Sackville-Bagginses enter, you may sacrifice another creature or artifact. If you do, draw a card and create a Treasure token.Whenever you sacrifice a token, target opponent loses 1 life.', 'It took more than Bilbo showing up alive to convince some that he was not, in fact, "presumed dead."', '2', '2', 'English', 'Alchemy, Brawl, Commander, Competitive Brawl, Historic, Legacy, Modern, Pioneer, Standard, Timeless, Vintage', 'https://gatherer-static.wizards.com/Cards/medium/7AD291CB99359B00174CC79CA2CD1907E349F1B6902BDA9AF9A7312268C71C16.webp', NULL);
